test('search collapses only spaces and tabs without rewriting persistent names or titles', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'workboard-search-spaces-'));
  let server;
  try {
    const dbPath = join(dir, 'db.sqlite');
